-- ============================================================
-- 01. TOTAL ORDERS AND REVENUE
-- Business Question:
-- What are the total orders and revenue generated by Olist?
--
-- Purpose:
-- Measure overall sales performance.
-- Revenue measures are calculated separately to avoid confusion.
-- ============================================================

SELECT
    COUNT(DISTINCT o.order_id) AS total_orders,

    COUNT(DISTINCT CASE
        WHEN o.order_status = 'delivered'
        THEN o.order_id
    END) AS delivered_orders,

    ROUND(
        SUM(oi.price)::NUMERIC,
        2
    ) AS total_product_sales,

    ROUND(
        SUM(oi.freight_value)::NUMERIC,
        2
    ) AS total_freight_value,

    ROUND(
        SUM(oi.price + oi.freight_value)::NUMERIC,
        2
    ) AS product_sales_plus_freight

FROM orders o
LEFT JOIN order_items oi
    ON o.order_id = oi.order_id;

-- ============================================================
-- 02. TOTAL CUSTOMER PAYMENT VALUE
-- Business Question:
-- What is the total payment value recorded in the dataset?
--
-- Purpose:
-- Measure payments independently of item-level sales.
-- ============================================================

SELECT
    ROUND(
        SUM(payment_value)::NUMERIC,
        2
    ) AS total_payment_value

FROM order_payments;

-- ============================================================
-- 03. MONTHLY SALES ANALYSIS
-- Business Question:
-- How do sales and order volumes change each month?
--
-- Purpose:
-- Identify monthly trends and seasonal patterns.
-- ============================================================

SELECT
    DATE_TRUNC(
        'month',
        o.order_purchase_timestamp
    )::DATE AS sales_month,

    COUNT(DISTINCT o.order_id) AS total_orders,

    ROUND(
        SUM(oi.price)::NUMERIC,
        2
    ) AS product_sales,

    ROUND(
        SUM(oi.price + oi.freight_value)::NUMERIC,
        2
    ) AS sales_plus_freight

FROM orders o
INNER JOIN order_items oi
    ON o.order_id = oi.order_id

GROUP BY
    DATE_TRUNC(
        'month',
        o.order_purchase_timestamp
    )

ORDER BY sales_month;

-- ============================================================
-- 04. YEARLY SALES ANALYSIS
-- Business Question:
-- How do sales and order volumes change each year?
--
-- Purpose:
-- Compare annual sales performance.
-- ============================================================

SELECT
    EXTRACT(
        YEAR FROM o.order_purchase_timestamp
    )::INT AS sales_year,

    COUNT(DISTINCT o.order_id) AS total_orders,

    ROUND(
        SUM(oi.price)::NUMERIC,
        2
    ) AS product_sales,

    ROUND(
        SUM(oi.price + oi.freight_value)::NUMERIC,
        2
    ) AS sales_plus_freight

FROM orders o
INNER JOIN order_items oi
    ON o.order_id = oi.order_id

GROUP BY
    EXTRACT(
        YEAR FROM o.order_purchase_timestamp
    )

ORDER BY sales_year;